import {componentDefaults} from './scene-components.js';
import {sceneWorldMatrix} from './scene-runtime.js';
export function clothTetherAuthoringSource(input,root,{running,objects,selected,selectedDetail,detailTarget}){if(running)throw Error('실행을 멈춘 뒤 연결을 생성하세요.');if(input.isConnected===false)throw Error('컴포넌트가 바뀌었어요.');if(input.dataset.sceneComponent){const object=objects.find(o=>o.id===selected);if(!object||root.dataset.clothDistanceOwner!==object.id)throw Error('선택한 오브젝트가 바뀌었어요.');const c=(object.components||[]).find(c=>c.id===input.dataset.sceneComponent);if(!c||c.id!==root.dataset.clothDistanceComponent)throw Error('컴포넌트가 바뀌었어요.');return{properties:{...componentDefaults(c.type),...c.properties},matrix:sceneWorldMatrix(object,objects),dimension:c.type==='Rope2D'?2:3};}const c=detailTarget();if(selectedDetail.kind!=='component'||!c||c.id!==root.dataset.clothDistanceComponent)throw Error('선택한 컴포넌트가 바뀌었어요.');return{properties:{...componentDefaults(c.type),...c.properties},dimension:c.type==='Rope2D'?2:3};}
